-- Metadata-only fixture for a disposable local database.
CREATE SCHEMA IF NOT EXISTS auth;
DO $$ BEGIN CREATE ROLE authenticated NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE anon NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE OR REPLACE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid $$;
GRANT USAGE ON SCHEMA auth TO authenticated;
CREATE TABLE public."activity_log" ("id" bigserial NOT NULL,"timestamp" text NOT NULL,"action" text NOT NULL,"entity_type" text NOT NULL,"entity_id" bigint,"description" text NOT NULL);
CREATE TABLE public."bbc_services" ("id" bigserial NOT NULL,"title" text NOT NULL,"description" text NOT NULL DEFAULT ''::text,"sort_order" integer NOT NULL DEFAULT 0,"active" boolean NOT NULL DEFAULT true);
CREATE TABLE public."boats" ("id" bigserial NOT NULL,"customer_id" bigint NOT NULL,"make" text NOT NULL,"model" text,"year" integer,"color" text,"length" real,"engine_type" text,"engine_make" text,"engine_model" text,"engine_hours" real,"horsepower" integer,"hull_id" text,"registration_number" text,"storage_location" text,"notes" text,"reminders" text DEFAULT '[]'::text,"sticky_note" text,"engine_serial" text,"transom_serial" text,"drive_serial" text);
CREATE TABLE public."catalog_tabs" ("id" bigserial NOT NULL,"label" text NOT NULL,"sort_order" integer NOT NULL DEFAULT 0,"match_prefix" text);
CREATE TABLE public."common_jobs" ("id" bigserial NOT NULL,"name" text NOT NULL,"description" text,"pricing_type" text DEFAULT 'hourly'::text,"labor_hours" real DEFAULT 0,"labor_rate" real DEFAULT 110,"flat_rate" real,"category" text);
CREATE TABLE public."customer_comm_log" ("id" bigserial NOT NULL,"customer_id" bigint,"timestamp" text NOT NULL,"type" text NOT NULL,"notes" text);
CREATE TABLE public."customers" ("id" bigserial NOT NULL,"name" text NOT NULL,"phone" text,"email" text,"address" text,"notes" text);
CREATE TABLE public."labor_codes" ("id" bigserial NOT NULL,"code" text,"description" text NOT NULL,"hours" real NOT NULL,"category" text);
CREATE TABLE public."parts" ("id" bigserial NOT NULL,"service_record_id" bigint NOT NULL,"part_number" text,"description" text NOT NULL,"quantity" real NOT NULL DEFAULT 1,"unit_price" real NOT NULL DEFAULT 0,"order_status" text,"catalog_part_id" bigint,"job_id" bigint,"included_in_flat_rate" boolean NOT NULL DEFAULT true);
CREATE TABLE public."parts_catalog" ("id" bigserial NOT NULL,"part_number" text,"description" text NOT NULL,"category" text,"cost_price" real DEFAULT 0,"sell_price" real DEFAULT 0,"qty_on_hand" real DEFAULT 0,"reorder_point" real DEFAULT 0,"notes" text,"is_common" integer DEFAULT 0);
CREATE TABLE public."quote_requests" ("id" bigserial NOT NULL,"name" text NOT NULL,"phone" text NOT NULL,"email" text,"boat_info" text,"service_type" text NOT NULL,"message" text,"status" text NOT NULL DEFAULT 'new'::text,"created_at" timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE public."scheduled_events" ("id" bigserial NOT NULL,"event_type" text NOT NULL,"scheduled_date" date NOT NULL,"time_slot" text NOT NULL,"customer_id" bigint,"boat_id" bigint,"service_record_id" bigint,"title" text NOT NULL,"notes" text,"status" text NOT NULL DEFAULT 'scheduled'::text,"sort_order" integer NOT NULL DEFAULT 0,"created_at" timestamp with time zone NOT NULL DEFAULT now(),"updated_at" timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE public."service_photos" ("id" bigserial NOT NULL,"service_record_id" bigint,"data_url" text,"caption" text,"created_at" text NOT NULL,"storage_url" text,"storage_path" text,"filename" text,"customer_id" bigint);
CREATE TABLE public."service_records" ("id" bigserial NOT NULL,"boat_id" bigint NOT NULL,"date" text NOT NULL,"description" text NOT NULL DEFAULT ''::text,"tech_notes" text,"labor_hours" real,"cost" real,"status" text NOT NULL DEFAULT 'open'::text,"labor_rate" real DEFAULT 110,"deposit_amount" real,"paid" integer DEFAULT 0,"due_date" text,"signature_data_url" text,"signed_by" text,"signed_at" timestamp with time zone);
CREATE TABLE public."status_history" ("id" bigserial NOT NULL,"service_record_id" bigint NOT NULL,"status" text NOT NULL,"changed_at" timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE public."work_order_jobs" ("id" bigserial NOT NULL,"service_record_id" bigint NOT NULL,"name" text NOT NULL DEFAULT 'Job'::text,"description" text,"pricing_type" text DEFAULT 'hourly'::text,"labor_hours" real DEFAULT 0,"labor_rate" real DEFAULT 110,"flat_rate" real,"sort_order" integer DEFAULT 0,"customer_notes" text,"tech_notes" text,"status" text NOT NULL DEFAULT 'open'::text);
CREATE TABLE public."work_order_templates" ("id" bigserial NOT NULL,"name" text NOT NULL,"description" text,"jobs" text DEFAULT '[]'::text);
ALTER TABLE public."activity_log" ADD PRIMARY KEY (id);
ALTER TABLE public."bbc_services" ADD PRIMARY KEY (id);
ALTER TABLE public."boats" ADD PRIMARY KEY (id);
ALTER TABLE public."catalog_tabs" ADD PRIMARY KEY (id);
