ALTER TABLE public."boats" ADD FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE;
ALTER TABLE public."customer_comm_log" ADD FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE;
ALTER TABLE public."parts" ADD FOREIGN KEY (service_record_id) REFERENCES service_records(id) ON DELETE CASCADE;
ALTER TABLE public."scheduled_events" ADD FOREIGN KEY (boat_id) REFERENCES boats(id) ON DELETE SET NULL;
ALTER TABLE public."scheduled_events" ADD FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE SET NULL;
ALTER TABLE public."scheduled_events" ADD CHECK ((event_type = ANY (ARRAY['drop_off'::text, 'pickup'::text, 'other'::text])));
ALTER TABLE public."scheduled_events" ADD FOREIGN KEY (service_record_id) REFERENCES service_records(id) ON DELETE SET NULL;
ALTER TABLE public."scheduled_events" ADD CHECK ((status = ANY (ARRAY['scheduled'::text, 'done'::text, 'cancelled'::text])));
ALTER TABLE public."scheduled_events" ADD CHECK ((time_slot = ANY (ARRAY['am'::text, 'pm'::text])));
ALTER TABLE public."service_photos" ADD FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE;
ALTER TABLE public."service_photos" ADD FOREIGN KEY (service_record_id) REFERENCES service_records(id) ON DELETE CASCADE;
